<?php
$this->layout('layouts/studio');
$first = strtotime($month . '-01');
$start = (int)date('N', $first);
$days = (int)date('t', $first);
$byDay = [];
foreach ($events as $event) $byDay[(int)date('j', strtotime($event->starts_at))][] = $event;
$monthLabel = class_exists(\IntlDateFormatter::class)
    ? (new \IntlDateFormatter('pt_BR', \IntlDateFormatter::NONE, \IntlDateFormatter::NONE, date_default_timezone_get(), null, "MMMM 'de' yyyy"))->format($first)
    : date('m/Y', $first);
?>
<section class="studio-page-header"><div><p class="studio-eyebrow">Atendimento</p><h1 class="studio-page-title">Agenda</h1><p class="studio-page-description">Organize atendimentos, tarefas e compromissos do time em uma visão mensal.</p></div><div class="studio-page-actions"><button class="studio-btn primary" type="button" data-agenda-new><ion-icon name="add-outline"></ion-icon>Novo evento</button></div></section>
<form class="studio-agenda-filters studio-panel ajax_off" method="get" action="<?= url('/operation/agenda') ?>">
    <input type="hidden" name="month" value="<?= htmlspecialchars($month) ?>">
    <label>Tipo<select class="studio-select" name="type"><option value="">Todos</option><?php foreach(['visit'=>'Visita','meeting'=>'Reunião','support'=>'Chamado','task'=>'Tarefa','deadline'=>'Prazo'] as $value=>$label):?><option value="<?= $value ?>" <?= $typeFilter===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label>
    <label>Status<select class="studio-select" name="status"><option value="">Todos</option><?php foreach(['scheduled'=>'Agendado','completed'=>'Concluído','cancelled'=>'Cancelado'] as $value=>$label):?><option value="<?= $value ?>" <?= $statusFilter===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label>
    <label>Responsável<select class="studio-select" name="assigned_to"><option value="">Todos</option><?php foreach($users as $item):?><option value="<?= $item->id ?>" <?= $assignedFilter==$item->id?'selected':'' ?>><?= htmlspecialchars($item->fullName()) ?></option><?php endforeach;?></select></label>
    <label>Condomínio<select class="studio-select" name="condominium_id"><option value="">Todos</option><?php foreach($condominiums as $item):?><option value="<?= $item->id ?>" <?= $condominiumFilter==$item->id?'selected':'' ?>><?= htmlspecialchars($item->name) ?></option><?php endforeach;?></select></label>
    <button class="studio-btn" type="submit"><ion-icon name="filter-outline"></ion-icon>Aplicar</button>
    <?php if($typeFilter||$statusFilter||$assignedFilter||$condominiumFilter):?><a class="studio-btn" href="<?= url('/operation/agenda?month='.$month) ?>">Limpar</a><?php endif;?>
</form>
<nav class="operation-calendar-views" aria-label="Visualização da agenda"><?php foreach(['day'=>'Dia','week'=>'Semana','month'=>'Mês','list'=>'Agenda','map'=>'Mapa'] as $mode=>$label):?><a class="<?= $viewMode===$mode?'active':'' ?>" href="<?= url('/operation/agenda?'.http_build_query(array_filter(['month'=>$month,'view'=>$mode,'type'=>$typeFilter,'status'=>$statusFilter,'assigned_to'=>$assignedFilter,'condominium_id'=>$condominiumFilter]))) ?>"><?= $label ?></a><?php endforeach;?></nav>
<?php if(in_array($viewMode,['day','week','list'],true)): $visibleEvents=array_values(array_filter($events,static function($event)use($viewMode){$date=date('Y-m-d',strtotime($event->starts_at));if($viewMode==='day')return $date===date('Y-m-d');if($viewMode==='week')return date('o-W',strtotime($date))===date('o-W');return true;})); ?>
<section class="studio-panel operation-calendar-list"><header><div><p class="studio-eyebrow"><?= $viewMode==='day'?'Hoje':($viewMode==='week'?'Esta semana':'Agenda do mês') ?></p><h2>Programação operacional</h2></div><strong><?= count($visibleEvents) ?> item(ns)</strong></header><?php foreach($visibleEvents as $event):?><<?= $event->source_type==='visit'?'a':'button' ?> <?= $event->source_type==='visit'?'href="'.url('/operation/visitas/'.$event->id).'"':'type="button" data-agenda-event=\''.htmlspecialchars(json_encode(['id'=>(int)$event->id,'title'=>$event->title,'description'=>$event->description,'starts_at'=>date('Y-m-d\TH:i',strtotime($event->starts_at)),'ends_at'=>$event->ends_at?date('Y-m-d\TH:i',strtotime($event->ends_at)):'','type'=>$event->type,'status'=>$event->status,'assigned_to'=>$event->assigned_to,'condominium_id'=>$event->condominium_id],JSON_UNESCAPED_UNICODE),ENT_QUOTES,'UTF-8').'\'' ?>><time><strong><?= date_fmt($event->starts_at,'d/m') ?></strong><span><?= date_fmt($event->starts_at,'H:i') ?></span></time><i class="<?= htmlspecialchars($event->type) ?>"></i><span><small><?= htmlspecialchars($event->type.' · '.$event->status) ?></small><strong><?= htmlspecialchars($event->title) ?></strong><em><?= htmlspecialchars($event->condominium_name?:'Administradora') ?><?= $event->assigned_name?' · '.htmlspecialchars($event->assigned_name):'' ?></em></span><ion-icon name="chevron-forward-outline"></ion-icon></<?= $event->source_type==='visit'?'a':'button' ?>><?php endforeach;?><?php if(!$visibleEvents):?><div class="studio-empty">Nenhum compromisso nesta visualização. <button class="studio-btn" type="button" data-agenda-new>Agendar tempo</button></div><?php endif;?></section>
<?php elseif($viewMode==='map'): ?>
<section class="studio-panel operation-calendar-map"><header><div><p class="studio-eyebrow">Compromissos externos</p><h2>Mapa operacional</h2></div></header><div><?php foreach(array_filter($events,static fn($event)=>$event->latitude!==null&&$event->longitude!==null) as $event):?><a target="_blank" rel="noopener" href="https://www.google.com/maps?q=<?= rawurlencode($event->latitude.','.$event->longitude) ?>"><ion-icon name="location-outline"></ion-icon><span><strong><?= htmlspecialchars($event->title) ?></strong><small><?= htmlspecialchars($event->condominium_name) ?> · <?= date_fmt($event->starts_at,'d/m H:i') ?></small></span><em>Abrir rota</em></a><?php endforeach;?></div></section>
<?php else: ?>
<section class="studio-panel studio-agenda"><header class="studio-panel-header"><a class="studio-btn icon" href="<?= url('/operation/agenda?month='.date('Y-m',strtotime($month.'-01 -1 month'))) ?>" aria-label="Mês anterior"><ion-icon name="chevron-back-outline"></ion-icon></a><h2 class="studio-panel-title"><?= htmlspecialchars(ucfirst($monthLabel)) ?></h2><a class="studio-btn icon" href="<?= url('/operation/agenda?month='.date('Y-m',strtotime($month.'-01 +1 month'))) ?>" aria-label="Próximo mês"><ion-icon name="chevron-forward-outline"></ion-icon></a></header>
<div class="studio-agenda-weekdays"><span>Seg</span><span>Ter</span><span>Qua</span><span>Qui</span><span>Sex</span><span>Sáb</span><span>Dom</span></div><div class="studio-agenda-grid">
<?php for($blank=1;$blank<$start;$blank++): ?><div class="studio-agenda-day is-empty" aria-hidden="true"></div><?php endfor; ?>
<?php for($day=1;$day<=$days;$day++): ?><div class="studio-agenda-day <?= date('Y-m-d')===$month.'-'.str_pad((string)$day,2,'0',STR_PAD_LEFT)?'is-today':'' ?>"><strong><?= $day ?></strong><?php foreach($byDay[$day]??[] as $event): ?><?php if($event->source_type==='visit'):?><a class="studio-agenda-event visit <?= htmlspecialchars($event->status) ?>" href="<?= url('/operation/visitas/'.$event->id) ?>" title="<?= htmlspecialchars($event->title.' · '.$event->condominium_name) ?>"><span><?= date('H:i',strtotime($event->starts_at)) ?></span><?= htmlspecialchars($event->title) ?></a><?php else:?><button type="button" class="studio-agenda-event <?= htmlspecialchars($event->type.' '.$event->status) ?>" title="<?= htmlspecialchars($event->title.($event->condominium_name?' · '.$event->condominium_name:'')) ?>" data-agenda-event='<?= htmlspecialchars(json_encode(['id'=>(int)$event->id,'title'=>$event->title,'description'=>$event->description,'starts_at'=>date('Y-m-d\TH:i',strtotime($event->starts_at)),'ends_at'=>$event->ends_at?date('Y-m-d\TH:i',strtotime($event->ends_at)):'','recurrence_rule'=>$event->recurrence_rule,'reminder_minutes'=>$event->reminder_minutes,'location'=>$event->location,'type'=>$event->type,'status'=>$event->status,'assigned_to'=>$event->assigned_to,'condominium_id'=>$event->condominium_id],JSON_UNESCAPED_UNICODE),ENT_QUOTES,'UTF-8') ?>'><span><?= date('H:i',strtotime($event->starts_at)) ?></span><?= htmlspecialchars($event->title) ?></button><?php endif;?><?php endforeach;?></div><?php endfor; ?>
</div></section>
<?php endif; ?>
<div class="studio-modal" id="agenda-event-modal" data-studio-modal aria-hidden="true"><div class="studio-modal-dialog"><header class="studio-modal-header"><div><p class="studio-eyebrow">Calendário operacional</p><h2 class="studio-modal-title" data-agenda-modal-title>Agendar tempo</h2></div><button class="studio-modal-close" type="button" data-agenda-close aria-label="Fechar">×</button></header><form class="studio-form studio-modal-body" action="<?= url('/operation/agenda') ?>" method="post"><?= csrf_input() ?><input type="hidden" name="action" value="save"><input type="hidden" name="event_id" value=""><label>Título<input name="title" required></label><div class="studio-grid studio-grid-2"><label>Tipo<select name="type"><option value="meeting">Reunião</option><option value="support">Chamado</option><option value="task">Tarefa</option><option value="deadline">Prazo</option></select></label><label>Condomínio/contexto<select name="condominium_id"><option value="">Administradora</option><?php foreach($condominiums as $item):?><option value="<?= $item->id ?>"><?= htmlspecialchars($item->name) ?></option><?php endforeach;?></select></label></div><div class="studio-grid studio-grid-2"><label>Início<input type="datetime-local" name="starts_at" required></label><label>Fim<input type="datetime-local" name="ends_at"></label></div><div class="studio-grid studio-grid-2"><label>Responsável<select name="assigned_to"><option value="">Não definido</option><?php foreach($users as $item):?><option value="<?= $item->id ?>"><?= htmlspecialchars($item->fullName()) ?></option><?php endforeach;?></select></label><label>Participantes<select name="participants[]" multiple size="4"><?php foreach($users as $item):?><option value="<?= $item->id ?>"><?= htmlspecialchars($item->fullName()) ?></option><?php endforeach;?></select></label><label>Local<input name="location" placeholder="Endereço, sala ou link"></label><label>Recorrência<select name="recurrence_rule"><option value="">Não repetir</option><option value="FREQ=DAILY">Diariamente</option><option value="FREQ=WEEKLY">Semanalmente</option><option value="FREQ=MONTHLY">Mensalmente</option></select></label><label>Lembrete<select name="reminder_minutes"><option value="">Sem lembrete</option><option value="15">15 minutos antes</option><option value="30">30 minutos antes</option><option value="60">1 hora antes</option><option value="1440">1 dia antes</option></select></label><label>Status<select name="status"><option value="scheduled">Agendado</option><option value="completed">Concluído</option><option value="cancelled">Cancelado</option></select></label></div><label>Observações<textarea name="description" rows="4"></textarea></label><footer class="studio-modal-footer"><button class="studio-btn danger" type="submit" name="action" value="delete" data-agenda-delete hidden data-confirm-submit="Excluir este compromisso?">Excluir</button><button class="studio-btn" type="button" data-agenda-close>Cancelar</button><button class="studio-btn primary">Salvar</button></footer></form></div></div>
<?php $this->start('scripts') ?><script>
(()=>{const modal=document.querySelector('#agenda-event-modal'),form=modal?.querySelector('form'),title=modal?.querySelector('[data-agenda-modal-title]'),deleteButton=modal?.querySelector('[data-agenda-delete]');const instance=()=>window.StudioModal?.get(modal);const close=()=>instance()?.close();const open=data=>{form.reset();['event_id','title','description','starts_at','ends_at','type','status','assigned_to','condominium_id','recurrence_rule','reminder_minutes','location'].forEach(name=>{if(form.elements[name])form.elements[name].value=data?.[name]||''});form.starts_at.value=data?.starts_at||'<?= date('Y-m-d\TH:i') ?>';form.type.value=data?.type||'meeting';form.status.value=data?.status||'scheduled';title.textContent=data?.id?'Editar compromisso':'Agendar tempo';deleteButton.hidden=!data?.id;instance()?.open()};document.querySelector('[data-agenda-new]')?.addEventListener('click',()=>open());document.querySelectorAll('[data-agenda-event]').forEach(button=>button.addEventListener('click',()=>open(JSON.parse(button.dataset.agendaEvent))));modal?.querySelectorAll('[data-agenda-close]').forEach(button=>button.addEventListener('click',close));modal?.addEventListener('click',event=>{if(event.target===modal)close()});if(new URLSearchParams(location.search).get('new')==='1')open()})();
</script><?php $this->stop() ?>
